const N = Number.parseInt(process.argv[2], 10);

class TreeNode {
    constructor(left, right) {
        this.left = left;
        this.right = right;
    }
}

function buildTree(depth) {
    if (depth <= 0) {
        return new TreeNode(null, null);
    }

    const nextDepth = depth - 1;
    return new TreeNode(
        buildTree(nextDepth),
        buildTree(nextDepth)
    );
}

function itemCheck(node) {
    if (node.left === null) {
        return 1;
    }
    return 1 + itemCheck(node.left) + itemCheck(node.right);
}

const output = [];

const stretchDepth = N + 1;
let stretchTree = buildTree(stretchDepth);
output.push(`stretch tree of depth ${stretchDepth}\t check: ${itemCheck(stretchTree)}`);
stretchTree = null;

const longLivedTree = buildTree(N);

for (let depth = 4; depth <= N; depth += 2) {
    const iterations = Math.pow(2, N - depth + 4);
    let check = 0;

    for (let i = 0; i < iterations; i++) {
        let tree = buildTree(depth);
        check += itemCheck(tree);
        tree = null;
    }

    output.push(`${iterations}\t trees of depth ${depth}\t check: ${check}`);
}

output.push(`long lived tree of depth ${N}\t check: ${itemCheck(longLivedTree)}`);

