                    work.set(perm);
                    let k = first;

                    for (;;) {
                        for (let left = 0, right = k; left < right; left++, right--) {
                            const value = work[left];
                            work[left] = work[right];
                            work[right] = value;
                        }

                        k = work[0];
                        if (k === 0) break;
                        flips++;
